using System;using System.IO;using System.Linq;using System.Text.Json;using Exoduser.UnityPort.Core;
class Program {
 static void Main(string[] args){var map=JsonDocument.Parse(File.ReadAllText(args[0])).RootElement;int w=map.GetProperty("width").GetInt32(),h=map.GetProperty("height").GetInt32();var tiles=map.GetProperty("tiles").EnumerateArray().Select(x=>x.GetInt32()).ToArray();float sx=map.GetProperty("startX").GetSingle(),sy=map.GetProperty("startY").GetSingle();var col=map.GetProperty("colliders").EnumerateArray().Select(x=>new float[]{x.GetProperty("x").GetSingle(),x.GetProperty("y").GetSingle(),x.GetProperty("rx").GetSingle(),x.GetProperty("ry").GetSingle()}).ToArray();var names=JsonSerializer.Deserialize<string[]>(File.ReadAllText(args[1]));long[] total=new long[40],start=new long[40],holes=new long[40];int n=int.Parse(args[3]);long allCount=0;int minStart=999,maxStart=0;bool Floor(int x,int y)=>x>=0&&y>=0&&x<w&&y<h&&tiles[y*w+x]==0;bool Point(float x,float y){if(!Floor((int)(x/40),(int)(y/40)))return false;foreach(var c in col){double dx=(x-c[0])/c[2],dy=(y-c[1])/c[3];if(dx*dx+dy*dy<1)return false;}return true;}bool Pass(float x,float y,float r)=>Point(x-r,y-r)&&Point(x+r,y-r)&&Point(x-r,y+r)&&Point(x+r,y+r);
 for(uint seed=1;seed<=n;seed++){var cfg=new SimulationConfig{StartX=sx,StartY=sy,StageIndex=0,EnemyAiEnabled=false};var s=new Simulation(cfg,seed);s.MapTilesWide=w;s.MapTilesHigh=h;s.CanMove=Pass;s.IsProjectileWall=(x,y)=>!Point(x,y);s.FloorTile=Floor;s.Stage.InitializeField(tiles,w);s.EnableFieldSpawns();s.SpawnStartEnemies();int ns=s.Enemies.Count;minStart=Math.Min(minStart,ns);maxStart=Math.Max(maxStart,ns);foreach(var sh in s.SpawnHoles.Holes)sh.Triggered=true;for(int tick=120;tick<1200&&s.SpawnHoles.Holes.Count>0;tick++)s.SpawnHoles.Tick(tick,sx,sy,100000,0);if(s.SpawnHoles.Holes.Count!=0||s.Enemies.Count-ns!=168)throw new Exception("spawn planned count mismatch seed "+seed);for(int i=0;i<s.Enemies.Count;i++){var e=s.Enemies[i];if(e.IsBoss)continue;int idx=(int)e.Web._mob8Row.Value*8+(int)e.Web._mob8Col.Value;if(i<2&&idx!=8)throw new Exception("fixed start skin mismatch");total[idx]++;if(i<ns)start[idx]++;else holes[idx]++;allCount++;}}
 var ranked=Enumerable.Range(0,40).OrderByDescending(i=>total[i]).ThenBy(i=>i).Select(i=>new{idx=i,name=names[i],count=total[i],meanPerRun=(double)total[i]/n,initialCount=start[i],holeCount=holes[i]}).ToArray();File.WriteAllText(args[2],JsonSerializer.Serialize(new{scope="planned population sampling, all holes pre-activated, no AI/combat or camera/time weighting; not natural Player observation",sourceHead="5b45b6a482ab4c446137cb82f24ea4d10267d4f0",runs=n,seeds=new[]{1,n},plannedHoleCount=168,minStart,maxStart,allCount,ranked},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("runs="+n+" population="+allCount+" top5="+string.Join(",",ranked.Take(5).Select(x=>x.name+":"+x.count)));}
}
